CustomField.formula:
AND(
    Is_Open_Status__c = TRUE,

    OR(
        /* No first outreach within 24 hours of record creation */
        AND(
            ISBLANK(Outreach_Attempt_1__c),
            CreatedDate < (NOW() - 1)
        ),

        /* No second outreach within 48 hours of first outreach */
        AND(
            NOT(ISBLANK(Outreach_Attempt_1__c)),
            ISBLANK(Outreach_Attempt_2__c),
            Outreach_Attempt_1__c < (NOW() - 2)
        ),

        /* No third outreach within one week of second outreach */
        AND(
            NOT(ISBLANK(Outreach_Attempt_2__c)),
            ISBLANK(Outreach_Attempt_3__c),
            Outreach_Attempt_2__c < (NOW() - 7)
        )
    )
)
